// @generated by project-forge — visual-render-panels.mjs (blueprint, catalog, inspector, prototype & dialog fragments)
import { escapeHtml, escapeXml, sanitizeSafeHref, sanitizeSafeImgSrc, toRelPath } from './visual-layout.mjs'

export const MAX_PROTOTYPE_SRCDOC_BYTES = 512 * 1024

const DIFF_LABELS = { added: '新增', modified: '修改', removed: '拟移除', impacted: '受波及' }

function renderListItems(items, emptyText) {
  return Array.isArray(items) && items.length > 0
    ? `<ul class="pf-brief-list">${items.map((x) => `<li>${escapeHtml(x)}</li>`).join('')}</ul>`
    : `<p class="pf-muted-note">${escapeHtml(emptyText)}</p>`
}

function renderChangeCardHtml(item) {
  const st = item.diffState || 'modified'
  const label = DIFF_LABELS[st] || st
  const d = item.changeDetail || {}
  let detailHtml = ''
  if (d.before && d.after) {
    detailHtml = `<div class="pf-ba-row"><span class="pf-ba-old">${escapeHtml(d.before)}</span><span class="pf-ba-arr">→</span><span class="pf-ba-new">${escapeHtml(d.after)}</span></div>`
  } else if (d.reason) {
    const rep = d.replacementId ? ` · 替代：${escapeHtml(d.replacementId)}` : ''
    detailHtml = `<p class="pf-chg-note">${escapeHtml(d.reason)}${rep}</p>`
  } else if (d.note) {
    detailHtml = `<p class="pf-chg-note">${escapeHtml(d.note)}</p>`
  } else if (Array.isArray(item.impactReasons) && item.impactReasons.length > 0) {
    detailHtml = `<p class="pf-chg-note">${escapeHtml(item.impactReasons.join('；'))}</p>`
  } else if (item.summary) {
    detailHtml = `<p class="pf-chg-note">${escapeHtml(item.summary)}</p>`
  }
  return `<button type="button" class="pf-chg-card pf-chg-${escapeXml(st)}" data-target-id="${escapeXml(item.id)}"><div class="pf-chg-head"><strong>${escapeHtml(item.title)}</strong><span class="pf-pill pf-pill-${escapeXml(st)}">${escapeXml(label)}</span></div><span class="pf-muted-note">${escapeHtml(item.domainTitle || item.domain)}</span>${detailHtml}</button>`
}

function deriveChangeGroupsFromTree(tree) {
  const groups = { added: [], modified: [], removed: [], impacted: [] }
  for (const n of tree?.nodes || []) {
    if (groups[n.diffState]) {
      groups[n.diffState].push({
        id: n.id, title: n.title, domain: n.domain, domainTitle: n.domainTitle,
        diffState: n.diffState, changeDetail: n.changeDetail, impactReasons: n.impactReasons || [], summary: n.description || '',
      })
    }
  }
  return groups
}

export function renderBlueprintLandingHtml(model, verdict, verdictLabel) {
  const bd = model?.briefData
  const counts = model?.overlayCounts || { added: 0, modified: 0, removed: 0, impacted: 0 }
  const groups = bd?.changeGroups || deriveChangeGroupsFromTree(model?.tree)
  const allChanged = [
    ...(groups.added || []),
    ...(groups.modified || []),
    ...(groups.removed || []),
    ...(groups.impacted || []),
  ]
  const countersHtml = [
    ['added', '新增模块', counts.added || 0],
    ['modified', '修改模块', counts.modified || 0],
    ['removed', '拟移除', counts.removed || 0],
    ['impacted', '受波及下游', counts.impacted || 0],
  ].map(([st, lbl, num]) => `<div class="pf-stat-box pf-stat-${st}"><span class="pf-stat-num">${num}</span><span class="pf-stat-lbl">${lbl}</span></div>`).join('')

  const changesHtml = allChanged.length > 0
    ? `<div class="pf-chg-grid">${allChanged.map(renderChangeCardHtml).join('')}</div>`
    : '<div class="pf-empty-box">当前尚未标记四态变更模块，可通过 --affected-feature / --add-feature / --remove-feature 标注。</div>'

  if (!bd) {
    return `<div class="pf-scroll-panel"><div class="pf-verdict-hero"><span class="pf-verdict-pill" data-tone="${escapeHtml(verdict.tone || 'pass')}">${verdictLabel}</span><p class="pf-verdict-copy">${escapeHtml(verdict.summary || '')}</p></div><div class="pf-stat-row">${countersHtml}</div>${changesHtml}</div>`
  }

  const slices = (bd.childSlices || []).map((s) => `${s.key}：${s.rel}（${s.status}${s.done ? '，已完成' : ''}）`)
  const masterItems = bd.masterPrd
    ? [`总控 PRD：${bd.masterPrd.rel}（${bd.masterPrd.status}，${bd.masterPrd.approved ? '已批准' : '未批准'}）`, ...slices]
    : slices
  const wtItems = (bd.activeWorktrees || []).map((w) => `工作树 ${w.taskId} [${w.status}] ${w.branch || ''}`.trim())
  const openItems = [...(bd.mergedOpen || []), ...(bd.pendingDecisions || []).map((p) => `${p.file}:${p.line} ${p.text}`)]

  return [
    '<div class="pf-scroll-panel">',
    `<div class="pf-verdict-hero"><span class="pf-verdict-pill" data-tone="${escapeHtml(verdict.tone || 'pass')}">${verdictLabel}</span><p class="pf-verdict-copy">${escapeHtml(bd.verdict || verdict.summary || '')}</p></div>`,
    `<div class="pf-stat-row">${countersHtml}</div>`,
    `<section class="pf-bp-sec"><h3 class="pf-bp-h">四态变更清单（点击查看详请）</h3>${changesHtml}</section>`,
    '<div class="pf-brief-grid">',
    `<section class="pf-brief-card"><h3>核心目标与不做边界</h3><span class="pf-inspector-label">目标</span>${renderListItems(bd.goals, '暂未登记目标')}<span class="pf-inspector-label">不做边界</span>${renderListItems(bd.nonGoals, '暂未登记不做边界')}</section>`,
    `<section class="pf-brief-card"><h3>流程变化与 1:N 切片</h3><span class="pf-inspector-label">流程增量</span>${renderListItems(bd.flowDeltas, '暂无流程变更记录')}<span class="pf-inspector-label">切片与工作树</span>${renderListItems([...masterItems, ...wtItems], '独立规划（无 1:N 切片或额外工作树）')}</section>`,
    `<section class="pf-brief-card"><h3>已拍板决策</h3>${renderListItems(bd.mergedDecisions, '暂无已拍板决策')}</section>`,
    `<section class="pf-brief-card"><h3>待确认问题</h3>${renderListItems(openItems, '待拍板事项已清零')}</section>`,
    '</div></div>',
  ].join('\n')
}

export function renderCatalogHtml(tree) {
  const nodes = tree?.nodes || []
  const domains = tree?.domains || []
  if (nodes.length === 0) return '<div class="pf-empty-box">暂无已映射模块。</div>'
  const byDom = new Map()
  for (const d of domains) byDom.set(d.id, { dom: d, items: [] })
  for (const n of nodes) {
    if (!byDom.has(n.domain)) byDom.set(n.domain, { dom: { id: n.domain, title: n.domainTitle || n.domain, palette: n.palette }, items: [] })
    byDom.get(n.domain).items.push(n)
  }
  return Array.from(byDom.values()).filter((g) => g.items.length > 0).map((g) => {
    const color = escapeXml(g.dom.palette?.stroke || '#1b5e6b')
    const itemsHtml = g.items.map((n) => {
      const diffText = DIFF_LABELS[n.diffState] || ''
      const badge = diffText ? `<span class="pf-pill pf-pill-${escapeXml(n.diffState)}">${escapeXml(diffText)}</span>` : ''
      const sub = n.shortSummary || toRelPath(n.primaryAnchor || n.entrypoints?.[0] || n.modules?.[0] || '') || n.id
      return `<div class="pf-catalog-item" tabindex="0" role="button" data-target-id="${escapeXml(n.id)}"><div class="pf-catalog-head"><span>${escapeHtml(n.title)}</span>${badge}</div><p class="pf-catalog-paths">${escapeHtml(sub)}</p></div>`
    }).join('')
    return `<section class="pf-catalog-group" data-domain-group="${escapeXml(g.dom.id)}"><div class="pf-catalog-dom"><span class="pf-catalog-dom-left"><span class="pf-dot" style="background:${color}"></span><span>${escapeHtml(g.dom.title)}</span></span><span>${g.items.length}</span></div>${itemsHtml}</section>`
  }).join('\n')
}

export function renderDiffRowsHtml(nodes) {
  const active = (nodes || []).filter((n) => n.diffState !== 'context')
  if (active.length === 0) return '<div class="pf-empty-box">当前无活跃变更，所有模块均处于已同步状态。</div>'
  return active.map((n) => renderChangeCardHtml({
    id: n.id,
    title: n.title,
    domain: n.domain,
    domainTitle: n.domainTitle,
    diffState: n.diffState,
    changeDetail: n.changeDetail,
    impactReasons: n.impactReasons,
    summary: n.description,
  })).join('\n')
}

